// Kumaraswamy random number generator
// a and b are the shape parameters via https://en.wikipedia.org/wiki/Kumaraswamy_distribution
float kumaraswamyRandom(float u, float a, float b) {
    return pow(1.0 - pow(1.0 - u, 1.0 / b), 1.0 / a);
}

// Hashing function to generate a unique seed for each pixel
float hash(vec2 p) {
    p = 50.0 * fract(p * 0.3183099 + vec2(0.71, 0.113));
    return fract(p.x * p.y * (p.x + p.y));
}

// Generic pseudo-random number generator via pixel-unique seeding
float random(vec2 st) {
    float seed = hash(st);
    return fract(sin(dot(st.xy + seed, vec2(12.9898, 78.233))) * 43758.5453123);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = fragCoord.xy / iResolution.xy;

    // Kumaraswamy parameters
    float a = 1.0;
    float b = 1.5;

    float u = random(uv * iResolution.xy + iTime);
    float kumaraswamyValue = kumaraswamyRandom(u, a, b);

    // Visualize the output as a color gradient
    fragColor = vec4(vec3(kumaraswamyValue), 1.0);
}
